"""Small, public system-design lessons for each day of the shared course.

These authored examples need no account data or generated content. Each day has
an explicit lesson so a beginner can learn before opening an advanced reading.
"""
from __future__ import annotations

from copy import deepcopy


def _card(title, idea, example, steps, task, answer, words):
    return dict(title=title, idea=idea, example=example, steps=steps,
                task=task, answer=answer, words=words)


